PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX obo: <http://purl.obolibrary.org/obo/>
PREFIX sio: <http://semanticscience.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.geneontology.org/formats/oboInOwl#>

SELECT DISTINCT ?name_gen
WHERE {
  GRAPH <http://rdf.biogateway.eu/graph/prot2bp> {
    	?protein obo:RO_0002331 ?process_biologic.
  }
  GRAPH <http://rdf.biogateway.eu/graph/go> {
    	?process_biologic rdfs:label ?name_process_biologic;
	    owl:hasExactSynonym ?synonym_proccess_biologic.
        FILTER (REGEX(?name_process_biologic, "DNA repair", "i") || REGEX(?synonym_proccess_biologic, "DNA repair", "i"))
  }
  GRAPH <http://rdf.biogateway.eu/graph/gene> {
	?uri_gen rdfs:subClassOf <http://semanticscience.org/resource/SIO_010035>;
    	sio:SIO_010078 ?protein;
        skos:prefLabel ?name_gen;
		obo:RO_0002162 ?taxon.
  }
    GRAPH <http://rdf.biogateway.eu/graph/taxon> {
    	?taxon rdfs:label "Homo sapiens".
  }
}

PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
