  }
GRAPH <http://rdf.biogateway.eu/graph/gene> {
	?uri_gen_disease rdfs:subClassOf <http://semanticscience.org/resource/SIO_010035>;
	sio:SIO_010078 ?encoded_protein;
	obo:RO_0002162 ?taxon.
}
GRAPH <http://rdf.biogateway.eu/graph/prot> {
	?encoded_protein rdfs:subClassOf <http://semanticscience.org/resource/SIO_010043>;
    skos:prefLabel ?name_protein.
	}
GRAPH <http://rdf.biogateway.eu/graph/omim> {
   ?disease skos:prefLabel ?name_disease;
   skos:altLabel ?alternative_name_disease.
	FILTER(REGEX(?name_disease,"parkinson","i") || REGEX(?alternative_name_disease,"parkinson","i"))
}
GRAPH <http://rdf.biogateway.eu/graph/taxon> {
    ?taxon rdfs:label "Homo sapiens".
  	}
}

